  'detail.importNotice': { en: 'Only text content and image links from the target page are used to generate a draft. The original layout and styles are not copied. Confirm that you have rights to use the imported text and images.', ja: '対象ページのテキストと画像リンクだけを使って下書きを生成します。元サイトのレイアウトやスタイルはコピーしません。インポートするテキストと画像を使用する権利があることを確認してください。', 'zh-CN': '仅提取目标页面的文字内容与图片链接生成草稿，不复制原站版式与样式；请确认您有权使用导入的文字与图片内容。', 'zh-TW': '僅提取目標頁面的文字內容與圖片連結來產生草稿，不會複製原站版式與樣式；請確認您有權使用匯入的文字與圖片內容。' },
  'detail.importLoading': { en: 'Fetching and generating. This may take 1-2 minutes.', ja: '取得して生成中です。1〜2分かかる場合があります。', 'zh-CN': '抓取并生成中，可能需要 1-2 分钟', 'zh-TW': '擷取並產生中，可能需要 1-2 分鐘' },
