  'detail.generatePageTitle': { en: 'Generate page with AI ({title})', ja: 'AI でページを生成（{title}）', 'zh-CN': 'AI 整页生成（{title}）', 'zh-TW': 'AI 整頁產生（{title}）' },
  'detail.generatePlaceholder': { en: 'e.g. Design a calm, natural brand page for a seaside guesthouse, highlighting a walk to the beach, family facilities, and stay policies. Keep the tone warm and restrained.', ja: '例：海辺のゲストハウス向けに、静かで自然なブランドページをデザインしてください。ビーチまで徒歩、ファミリー向け設備、宿泊ポリシーを強調し、温かく控えめな語調にしてください。', 'zh-CN': '例如：为海边民宿设计安静、自然的品牌页，突出步行到海滩、亲子设施和入住政策。语气温暖克制。', 'zh-TW': '例如：為海邊民宿設計安靜、自然的品牌頁，突出步行到海灘、親子設施和入住政策。語氣溫暖克制。' },
  'detail.safetyBoundary': { en: 'Safety boundary', ja: '安全境界', 'zh-CN': '安全边界', 'zh-TW': '安全邊界' },
  'detail.safetyBoundaryDescription': { en: 'The prompt is sent to the system backend through the property-scoped AI channel. The browser neither stores model keys nor executes model-generated HTML or JavaScript. Generated content enters the editor and goes live only after it is saved as a draft and published.', ja: 'プロンプトは、システムバックエンドの施設単位 AI チャネルへ送信されます。ブラウザーはモデルキーを保存せず、モデルが生成した HTML や JavaScript も実行しません。生成結果はエディターに入り、下書きを保存して公開した後にのみ公開されます。', 'zh-CN': '提示词发送到系统后端的门店级 AI 通道；浏览器不保存模型密钥，也不执行模型生成的 HTML 或 JavaScript。生成结果进入编辑器，保存草稿并发布后才会上线。', 'zh-TW': '提示詞會送到系統後端的門店級 AI 通道；瀏覽器不保存模型金鑰，也不執行模型產生的 HTML 或 JavaScript。產生結果進入編輯器，儲存草稿並發布後才會上線。' },
  'detail.generateDraft': { en: 'Generate draft', ja: '下書きを生成', 'zh-CN': '生成草稿', 'zh-TW': '產生草稿' },
  'detail.closeEditorConfirm': { en: 'This page has unsaved changes. Close the editor anyway?', ja: 'このページには未保存の変更があります。編集画面を閉じますか？', 'zh-CN': '当前页面有未保存修改，确定关闭编辑器吗？', 'zh-TW': '目前頁面有未儲存修改，確定關閉編輯器嗎？' },
  'detail.closeEditorTitle': { en: 'Close page editor', ja: 'ページ編集を閉じる', 'zh-CN': '关闭页面编辑器', 'zh-TW': '關閉頁面編輯器' },
