const buildMessages = (locale: IndependentSiteLocale) => {
  const independentSite: Record<string, unknown> = {}

  for (const [path, translation] of Object.entries(translations)) {
    const segments = path.split('.')
    let current = independentSite
    for (const segment of segments.slice(0, -1)) {
      const existing = current[segment]
      if (!existing || typeof existing !== 'object' || Array.isArray(existing)) {
        current[segment] = {}
      }
      current = current[segment] as Record<string, unknown>
    }
    current[segments[segments.length - 1]] = translation[locale]
  }

  return { independentSite }
}

export const independentSiteMessages = {
  en: buildMessages('en'),
  ja: buildMessages('ja'),
  'zh-CN': buildMessages('zh-CN'),
  'zh-TW': buildMessages('zh-TW'),
} as const
